@dataclass(frozen=True)
class Link:                       # RFC 8288-style link element (rel + href)
    rel: str
    href: str                     # relative reference, resolved at use time
    method: str = "GET"

def payment_link(order) -> Link:  # Link Producer
    return Link("payment", f"/payments/{order.id}")

link = next(l for l in order._links if l.rel == "payment")  # Link Consumer
assert link.method == "GET"
conn.request(link.method, urljoin(BASE, link.href))  # dereference via http.client
